#!/usr/bin/env python3
"""Check (default) or refresh the pinned hook-only Pi extension without --apply."""
import argparse
from pathlib import Path
import subprocess
import tempfile

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--binary", default="ai-memory")
parser.add_argument("--write", action="store_true")
args = parser.parse_args()
version = subprocess.check_output([args.binary, "--version"], text=True).strip()
if version != "ai-memory 2.1.0":
    raise SystemExit(f"Expected ai-memory 2.1.0, got {version}")
extensions = Path(__file__).resolve().parent.parent
with tempfile.TemporaryDirectory(prefix="ai-memory-pi-vendor-") as directory:
    root = Path(directory)
    generated = subprocess.check_output([
        args.binary, "install-hooks", "--agent", "pi", "--server-url",
        "http://127.0.0.1:49374", "--data-dir", str(root / "data"),
    ], text=True)
    marker = "// Auto-generated by `ai-memory install-hooks --agent pi --apply`."
    source = generated[generated.index(marker):].rstrip() + "\n"
    target = root / "configs/agents/pi/extensions/ai-memory-pi.ts"
    target.parent.mkdir(parents=True)
    target.write_text(source)
    subprocess.run([
        "patch", "--batch", "--fuzz=0", "-p1", "-i",
        str(extensions / "vendor/ai-memory-pi-native-mcp.patch"),
    ], cwd=root, check=True)
    result = target.read_text()
    installed = extensions / "ai-memory-pi.ts"
    if args.write:
        installed.write_text(result)
        print(f"Refreshed {installed}")
    elif installed.read_text() != result:
        raise SystemExit("Vendored extension differs: review upstream/patch, then run with --write")
    else:
        print("Pinned ai-memory 2.1.0 + hook-only patch matches vendored extension")
